ham:
{
  "alintilar": [
    {
      "kaynak": "K1",
      "metin": "Bu fıkraya göre izinli sayılmak isteyen öğrencinin ilan edilen akademik takvimde belirtilen ders başlangıç tarihinden en az 10 iş günü öncesinde kayıtlı olduğu birime yazılı olarak başvurması zorunludur."
    }
  ],
  "cevap": "Ders başlangıç tarihinden en az 10 iş günü önce yazılı olarak başvurunuz gerekir [K1]. Bu süre, haklı ve geçerli bir mazerete dayanarak izinli ayrılma talepleri için geçerlidir [K1].",
  "ayrintilar": [
    "İzinli ayrılma talebinin uygunluğu ile iznin başlangıç tarihi ve süresi hakkında birim yönetim kurulu karar verir [K1].",
    "Hastalık, doğal afetler veya tutukluluk gibi hallerde ise durumun ortaya çıkmasından itibaren en geç 10 iş günü içinde başvuru yapılması gerekir [K1]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K1",
      "metin": "Öğrencinin belirtilen hallerin ortaya çıkmasından itibaren en geç 10 iş günü içinde durumunu kanıtlayan belgelerle kayıtlı olduğu birime başvurması gerekir."
    }
  ],
  "cevap": "Hastalık nedeniyle izinli ayrılma (kayıt dondurma) talebinde bulunmak için, belirtilen halin ortaya çıkmasından itibaren en geç 10 iş günü içinde durumunuzu kanıtlayan belgelerle kayıtlı olduğunuz birime başvurmanız gerekir [K1].",
  "ayrintilar": [
    "Talebin uygun olup olmadığı ile iznin başlangıç tarihi ve süresi hakkında birim yönetim kurulu karar verir [K1].",
    "Rahatsızlığı ve tedavi süreci devam eden öğrenciler, aynı usulle yeniden yazılı olarak başvurabilirler [K1]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K1",
      "metin": "Öğrencilerin; kuramsal derslere en az %70, uygulama, laboratuvar, işyeri eğitimi ve benzeri çalışmalara en az %80 oranında devamı zorunludur."
    },
    {
      "kaynak": "K2",
      "metin": "Hazırlık sınıfına katılan öğrenciler uygulanan öğretim planına göre almaları gereken derslerin %80’ine devam etmek zorundadırlar."
    }
  ],
  "cevap": "Kuramsal derslere en az %70, uygulama, laboratuvar ve işyeri eğitimi gibi çalışmalara ise en az %80 oranında devam etmeniz zorunludur [K1]. Hazırlık sınıfı öğrencileri için bu oran tüm dersler için %80'dir [K2].",
  "ayrintilar": [
    "Tıp, Veteriner, Sağlık Bilimleri, Diş Hekimliği Fakülteleri ve Güzel Sanatlar Fakültesi gibi bazı birimler hariç, devam şartı sağlanmış olan derslerin tekrar alınmasında devam zorunluluğu aranmaz [K1].",
    "Devam koşulunu sağlayamayan öğrenciler o dersten devamsız kabul edilir, sınavlara alınmaz ve notu D (Devamsız) olarak kaydedilir [K1]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K1",
      "metin": "(3) Aşağıda sayılanlar hariç olmak üzere, bir kez devam şartı sağlanmış olan salt teorik dersler ile derse bağlı uygulama ve laboratuvar derslerinin tekrar alınması durumunda devam zorunluluğu aranmaz:"
    },
    {
      "kaynak": "K1",
      "metin": "a) Tıp Fakültesi,"
    }
  ],
  "cevap": "Yönetmeliğe göre, bir kez devam şartı sağlanmış olan derslerin tekrar alınması durumunda devam zorunluluğu aranmaz; ancak bu kuralın istisnaları arasında Tıp Fakültesi de sayılmaktadır [K1]. Dolayısıyla Tıp Fakültesi öğrencisi olarak başarısız olduğunuz veya tekrar almak zorunda kaldığınız derslere devam etmek zorundasınız [K1].",
  "ayrintilar": [
    "Devam zorunluluğu kuramsal dersler için en az %70, uygulama ve laboratuvar dersleri için ise en az %80 oranındadır [K1].",
    "Devam şartını sağlamayan öğrenciler devamsız kabul edilir, sınavlara alınmaz ve not çizelgesinde D (Devamsız) ile belirtilir [K1]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K1",
      "metin": "GANO’su 1.80’in altında olan öğrenci yeni ders alamaz."
    },
    {
      "kaynak": "K2",
      "metin": "GANO’su 1.80’in altında olan öğrenci yeni ders alamaz, sadece başarısız olduğu dersler ile koşullu geçtiği dersleri alabilir."
    }
  ],
  "cevap": "Yönetmeliğe göre GANO'su 1.80'in altında olan öğrenciler yeni ders alamazlar [K1]. Bu durumda olan öğrenciler, not yükseltme amacıyla öncelikle başarısız oldukları derslerden başlamak ve dönemsel AKTS yükünü aşmamak kaydıyla geçmiş yıllardaki derslerine tekrar kaydolabilirler [K1].",
  "ayrintilar": [
    "Yaz öğretiminde de GANO'su 1.80'in altında olan öğrenciler sadece başarısız olduğu dersler ile koşullu geçtiği dersleri alabilir [K2]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K4",
      "metin": "(1) Kayıtlı olduğu önlisans programında en az 120 AKTS kredilik; lisans programında en az 240 AKTS kredilik; Diş Hekimliği Fakültesi ile Veteriner Fakültesinde en az 300 AKTS kredilik; Tıp Fakültesinde ise en az 360 AKTS kredilik dersi başarıyla tamamlayan, GANO’su en az 2.00 olan ve programa ait alması gereken tüm derslerin yükümlülüklerini yerine getiren öğrenciye, kayıtlı olduğu programın ön lisans veya lisans diploması, diploma eki ve not durum belgesi (transkript) verilir."
    },
    {
      "kaynak": "K1",
      "metin": "b) Kayıtlı olduğu Anadal Programından mezun olan ve İkinci Anadal Programını da 4.00 üzerinden en az 2.00 genel not ortalaması ile tamamlayan öğrenciye İkinci Anadal Lisans Programının diploması verilir."
    },
    {
      "kaynak": "K3",
      "metin": "(1) Üniversiteye 2013-2014 eğitim-öğretim yılı ve daha öncesinde kayıt yaptıran öğrenciler, mezuniyet için gereken AKTS kredi yükünü sağlayamamaları durumunda, kayıtlı oldukları programların tüm ders ve çalışmalarından başarılı olmaları ve GANO’larının en az 2.00 olması halinde mezun olmaya hak kazanırlar."
    }
  ],
  "cevap": "Yönetmeliğe göre önlisans için en az 120 AKTS, lisans için en az 240 AKTS; Diş Hekimliği ve Veteriner Fakülteleri için en az 300 AKTS, Tıp Fakültesi için ise en az 360 AKTS kredi ile GANO'su en az 2.00 olması gerekir [K4]. Çift anadal programlarında İkinci Anadal diploması almak için de 4.00 üzerinden en az 2.00 genel not ortalaması şarttır [K1].",
  "ayrintilar": [
    "2013-2014 ve daha önceki yıllarda kayıt yapan öğrenciler, AKTS yükünü sağlayamasalar bile tüm derslerden başarılı olup GANO'su en az 2.00 ise mezun olabilirler [K3].",
    "Mezuniyet tarihi, tüm eğitim-öğretim çalışmalarının ve sınavların başarılmasına, varsa stajların tamamlanmasına bağlı olarak birim yönetim kurulu kararı ile belirlenir [K4]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K3",
      "metin": "Lisans veya önlisans programındaki tüm dersleri alan, devam koşulunu yerine getirerek yarıyıl/yıl sonu sınavlarına giren öğrenciye, aşağıdaki koşullarda ek sınav hakkı verilir:"
    },
    {
      "kaynak": "K3",
      "metin": "a) Not ortalamasına katılan en çok iki dersten (FF) veya (FD) notu alan veya bir dersten çok olmamak şartıyla, kredisiz dersinden (K) alan öğrenciye bir sonraki yarıyılın/yılın başına kadar ek sınav hakkı verilir."
    },
    {
      "kaynak": "K3",
      "metin": "b) Mezun olmaları için gerekli 2.00 GANO’yu sağlayamayan öğrencilere, GANO’sunu yükseltebilmeleri için en çok iki dersten ek sınav hakkı verilir."
    }
  ],
  "cevap": "Yönetmeliğe göre, tüm dersleri alan ve devam koşulunu yerine getiren öğrencilerden; not ortalamasına katılan en çok iki dersten (FF) veya (FD) notu alanlar veya bir dersten (K) notu alanlara ek sınav hakkı verilir [K3]. Ayrıca mezuniyet için gerekli 2.00 GANO'yu sağlayamayan öğrencilere, not ortalamalarını yükseltmek amacıyla en çok iki dersten ek sınav hakkı tanınır [K3].",
  "ayrintilar": [
    "Bu ek sınav hakkından azami öğrenim süresi içinde sadece bir defa yararlanılabilir [K3].",
    "Ek sınav başvurusu, sınav sonuçlarının açıklanmasını izleyen 2 iş günü içinde dilekçe ile yapılmalıdır [K3].",
    "Zorunlu staj uygulaması olan birimlerde ek sınav hakkından yararlanabilmek için öğrencinin staja başlamış olması gerekir [K3]."
  ],
  "eksik": false
}

{
  "alintilar": [
    {
      "kaynak": "K1",
